import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}`),a={name:`architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="architecture" tabindex="-1" dir="auto">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><h2 id="shape" tabindex="-1" dir="auto">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to “Shape”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>            ┌────────────── scope:product ──────────────┐   ┌──── scope:dev ────┐</span></span>
<span class="line"><span> apps       │  site  ◄── site-e2e (Playwright)           │   │  sandbox          │</span></span>
<span class="line"><span>            │  docs  (VitePress over docs/)              │   │                   │</span></span>
<span class="line"><span>            └──────┬─────────────────────────────────────┘   └───┬───────────────┘</span></span>
<span class="line"><span>                   │ imports                                      │ imports</span></span>
<span class="line"><span>            ┌──────▼──────────────── scope:shared ────────────────▼───────────────┐</span></span>
<span class="line"><span> libs       │  ui (type:ui, Storybook) ──► shared-utils (type:util)               │</span></span>
<span class="line"><span>            └─────────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span> tools         vite-config (every app&#39;s vite.config)   workspace-plugin (pnpm new:*)</span></span>
<span class="line"><span>               pages (assemble + serve the Pages artifact)   security (pnpm security)</span></span></code></pre></div><ul><li dir="auto"><strong>Apps</strong> are thin: routing, pages, and composition. Anything reusable moves into a lib.</li><li dir="auto"><strong><code>ui</code></strong> is the design system: presentational components, Tailwind tokens (<code>src/styles.css</code>), and Storybook. It has no app logic, no data fetching and no routing.</li><li dir="auto"><strong><code>shared-utils</code></strong> is plain TypeScript with no React and no DOM, so it can be used anywhere (including Node scripts).</li><li dir="auto"><strong>Feature libs</strong> (<code>pnpm new:lib x --type=feature</code>) are where logic shared by several apps goes. None exist yet; create one when a second app needs the same feature.</li><li dir="auto"><strong><code>docs</code></strong> renders the Markdown in <code>docs/</code> as a site (VitePress, RTL Hebrew chrome). The files stay in <code>docs/</code>; the app holds no content (ADR <code>2026-10-03-docs-app</code>).</li><li dir="auto"><strong><code>sandbox</code></strong> is for spikes. Code there can import anything, but nothing may import from it. Promote a spike by moving its code into a lib or app, then delete the spike.</li></ul><h2 id="build-and-runtime" tabindex="-1" dir="auto">Build and runtime <a class="header-anchor" href="#build-and-runtime" aria-label="Permalink to “Build and runtime”">​</a></h2><ul><li dir="auto">Every app is a static Vite SPA. <code>tools/vite-config</code> sets the common config: React, Tailwind v4, Vitest (jsdom), <code>base</code> from <code>BASE_PATH</code>, and a <code>404.html</code> fallback for GitHub Pages deep links.</li><li dir="auto">Libraries are <strong>not built</strong>. Their <code>package.json</code> <code>exports</code> point at <code>src/index.ts</code>, and apps consume that source through pnpm workspace links, so there is no library build step or <code>dist</code> to keep in sync.</li><li dir="auto">TypeScript uses project references (<code>tsconfig.json</code> at each level). <code>nx sync</code> keeps them in line with <code>package.json</code> dependencies.</li></ul><h2 id="deployment" tabindex="-1" dir="auto">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to “Deployment”">​</a></h2><p dir="auto">A single GitHub Pages site per repo (<code>https://&lt;user&gt;.github.io/&lt;repo&gt;/</code>):</p><table tabindex="0"><thead><tr><th dir="auto">Path</th><th dir="auto">Content</th></tr></thead><tbody><tr><td dir="auto"><code>/</code></td><td dir="auto"><code>apps/site</code> production build</td></tr><tr><td dir="auto"><code>/storybook/</code></td><td dir="auto"><code>libs/ui</code> Storybook static build</td></tr><tr><td dir="auto"><code>/docs/</code></td><td dir="auto"><code>apps/docs</code> build of this folder</td></tr><tr><td dir="auto"><code>/pr-&lt;n&gt;/</code></td><td dir="auto"><code>apps/site</code> preview of PR <code>&lt;n&gt;</code></td></tr></tbody></table><p dir="auto"><code>tools/pages</code> assembles the artifact (<code>pnpm pages:build</code>) and refuses a site that already contains <code>storybook/</code>, <code>docs/</code>, a <code>pr-&lt;n&gt;/</code> path, source maps, or third-party scripts. <code>apps/pages-e2e</code> tests that exact artifact under a non-root base path with a Pages-like server. <code>.github/workflows/deploy.yml</code> publishes it to the root of the <code>gh-pages</code> branch, next to the PR previews that <code>preview.yml</code> puts under <code>pr-&lt;n&gt;/</code> (ADR 0004). <code>sandbox</code> is never deployed. The issue → PR agent pipeline is described in <code>docs/pipeline.md</code>.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};